\bibitem{ErdosProblem1} P.~Erd\H{o}s, open problem, 1931. See T.~Bloom,
\emph{Erd\H{o}s Problems}, \href{https://www.erdosproblems.com/1}{erdosproblems.com/1}.

\bibitem{ConwayGuy} J.~H.~Conway and R.~K.~Guy, \emph{Sets of natural numbers
with distinct subset sums}, Notices Amer.\ Math.\ Soc.\ \textbf{15} (1968), 345.

\bibitem{ErdosSpencer} P.~Erd\H{o}s and J.~Spencer, \emph{Probabilistic Methods
in Combinatorics}, Academic Press, 1974.
\end{thebibliography}

\end{document}

