49	Trabuco Canyon, California\\
50	\texttt{c.landonmills@gmail.com}\\
51	ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
52	\date{31 August 2026}
53	\maketitle
54	
55	\begin{abstract}
56	Let $F$ be a family of $2n$-element subsets of a $4n$-element set in which any
57	two members meet in at least two points. We give the short proof, by pairing
58	each $2n$-set with its complement, that $|F| \le \tfrac12 \binom{4n}{2n}$. The
59	argument uses nothing beyond the fact that a $2n$-subset of a $4n$-set and its
60	complement are themselves complementary $2n$-subsets, so the family cannot
61	contain both without violating 2-intersection. The sharp constant --- lower
62	than this half-bound by a term of order $\binom{2n}{n}^2$ --- belongs to the
63	general theory of $t$-intersecting families and is stated here as the
64	established result it is, not reproved.
65	\end{abstract}
66	
67	\section{The setup}
68	
69	\begin{definition}
70	Fix $n \ge 1$ and write $[4n] = \{1,\dots,4n\}$. A family $F$ of subsets of
71	$[4n]$ is \emph{2-intersecting at size $2n$} if every $A \in F$ has $|A|=2n$,
72	and $|A \cap B| \ge 2$ for all $A, B \in F$ (including $A=B$, which is
73	automatic).
74	\end{definition}
75	
76	Write $U(n)$ for the set of all $2n$-subsets of $[4n]$; $|U(n)| = \binom{4n}{2n}$.
77	The map $S \mapsto [4n] \smallsetminus S$ sends $U(n)$ to itself: the complement of
78	a $2n$-subset of a $4n$-set is again a $2n$-subset. It is also a fixed-point-free
79	involution on $U(n)$ once $n \ge 1$, since $S = [4n]\smallsetminus S$ would force
80	$|S| = 2n$ and $S \cap ([4n]\smallsetminus S) = S$, forcing $|S \cap S^c| = 2n \ge 2$,
81	which the next lemma rules out.
82	
83	\begin{lemma}[Complements are disjoint]
84	\label{lem:disjoint}
85	For every $S \subseteq [4n]$, $S \cap ([4n]\smallsetminus S) = \varnothing$.
86	\end{lemma}
87	
88	\begin{proof}
89	Immediate from the definition of set difference: no element of $[4n]\smallsetminus S$
90	belongs to $S$.
91	\end{proof}
92	
93	\section{The pairing bound}
94	
95	\begin{theorem}[Complement-pairing bound]
96	\label{thm:half}
97	If $F$ is 2-intersecting at size $2n$, then
98	\[
99	  \boxed{\; |F| \;\le\; \frac12 \binom{4n}{2n}. \;}
100	\]
101	\end{theorem}
102	
103	\begin{proof}
104	By \Cref{lem:disjoint}, $S$ and its complement $S^c$ are disjoint, so
105	$|S \cap S^c| = 0 < 2$. Hence $F$ cannot contain both $S$ and $S^c$ for any
106	$S \in U(n)$: that would violate 2-intersection. So $F$ meets each of the
107	$\binom{4n}{2n}/2$ complementary pairs in at most one member, giving
108	$|F| \le \binom{4n}{2n}/2$.
109	
110	The same fact runs as an injection, which is the form that formalizes
111	cleanly: complementation gives an injective map from $F$ into $U(n)\smallsetminus F$
112	(injective because it is an involution, and its image avoids $F$ because no
113	member of $F$'s complement can also lie in $F$). Hence $|F| \le |U(n)\smallsetminus F|
114	= \binom{4n}{2n} - |F|$, which rearranges to $2|F| \le \binom{4n}{2n}$.
115	\end{proof}
116	
117	\begin{figure}[h]
118	\centering
119	\begin{tikzpicture}[
120	  dot/.style={circle, draw, thick, minimum size=7mm, inner sep=0pt, font=\small},
121	  inF/.style={dot, fill=blue!25},
122	  notF/.style={dot, fill=white},
123	  pairline/.style={thick},
124	]
125	\foreach \i/\lab/\state in {0/S_1/inF, 1/S_1^c/notF, 3/S_2/notF, 4/S_2^c/inF,
126	                              6/S_3/inF, 7/S_3^c/notF, 9/S_4/notF, 10/S_4^c/notF} {
127	  \node[\state] (n\i) at (\i*0.85,0) {};
128	}
129	\draw[pairline] (n0) -- (n1);
130	\draw[pairline] (n3) -- (n4);
131	\draw[pairline] (n6) -- (n7);
132	\draw[pairline] (n9) -- (n10);
133	\node[below=0.15cm of n0, font=\scriptsize] {$S_1$};
134	\node[below=0.15cm of n1, font=\scriptsize] {$S_1^c$};
135	\node[below=0.15cm of n3, font=\scriptsize] {$S_2$};
136	\node[below=0.15cm of n4, font=\scriptsize] {$S_2^c$};
137	\node[below=0.15cm of n6, font=\scriptsize] {$S_3$};
138	\node[below=0.15cm of n7, font=\scriptsize] {$S_3^c$};
139	\node[below=0.15cm of n9, font=\scriptsize] {$S_4$};
140	\node[below=0.15cm of n10, font=\scriptsize] {$S_4^c$};
141	\node[left=0.4cm of n0, font=\small] {$U(n)$:};
142	\node[below=0.6cm of n4, font=\footnotesize, text width=8.5cm, align=center]
143	  {shaded $=$ member of $F$; each complementary pair holds at most one shaded node};
144	\end{tikzpicture}
145	\caption{$U(n)$ splits into $\binom{4n}{2n}/2$ complementary pairs. Two-intersection
146	forbids $F$ from taking both elements of any pair, so $F$ can shade at most one node
147	per pair --- at most half of $U(n)$ overall.}
148	\label{fig:pairing}
149	\end{figure}
150	
151	\section{Where the sharp bound lives}
152	
153	\Cref{thm:half} is not the extremal answer. The complete intersection theorem
154	for $t$-intersecting families --- established for the 1-intersecting case by
155	Wilson \cite{Wilson1984} following Erd\H{o}s, Ko and Rado's original theorem
156	\cite{EKR1961}, and for general $t$ by Ahlswede and Khachatrian
157	\cite{AhlswedeKhachatrian1997} --- gives the exact maximum for every
158	$t$-intersecting family of $k$-subsets of an $m$-set, as a function of $m$,
159	$k$, and $t$. Specialized to $t=2$, $k=2n$, $m=4n$, that theory produces a
160	bound strictly below $\tfrac12\binom{4n}{2n}$, by a correction term of order
161	$\binom{2n}{n}^2$: the extremal families are not the complement-avoiding
162	families this pairing argument bounds, but a sharper construction that the
163	pairing argument, by design, cannot see. \Cref{thm:half} is the bound the
164	complement involution alone supplies, and it is exactly as strong as that one
165	idea can make it.
166	
167	\section{Verification}
168	
169	\Cref{thm:half} is formalized in \Lean{} against Mathlib as an injection
170	$F \hookrightarrow U(n)\smallsetminus F$ built from the complement involution,
171	depending on \texttt{propext}, \texttt{Classical.choice}, and
172	\texttt{Quot.sound} only.
173	
174	\begin{thebibliography}{9}
