\newcommand{\Lean}{\textsf{Lean}\,4}

\begin{document}
\title{\textbf{The Erd\H{o}s--Faber--Lov\'asz Hypothesis Is Satisfiable}}
\author{C.\ Lando Mills\\
Trabuco Canyon, California\\
\texttt{c.landonmills@gmail.com}\\
ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
\date{31 August 2026}
\maketitle

\begin{abstract}
The Erd\H{o}s--Faber--Lov\'asz conjecture states that $n$ cliques of size $n$,
pairwise sharing at most one vertex, admit an $n$-colouring of their union. It
was proved for all sufficiently large $n$ by Kang, Kelly, K\"uhn, Methuku, and
Osthus in 2021 \cite{KangKellyKuhnMethukuOsthus2021}. We do not reprove it.
Instead we settle the question a formal statement of it needs answered first
and that the literature does not: whether the hypothesis --- $n$ cliques of
size $n$ meeting pairwise in at most one point --- is ever actually realized,
for every $n$, as opposed to being vacuous on some formalization of the
setup. We give the explicit family that realizes it at every $n$, and prove
it.
\end{abstract}

\section{The conjecture}

\begin{definition}
Let $V$ be a set. A family of cliques $C_1, \dots, C_n \subseteq V$, each of
size $n$, is an \emph{Erd\H{o}s--Faber--Lov\'asz family} if $|C_i \cap C_j|
\le 1$ for every $i \ne j$.
\end{definition}

\begin{figure}[h]
\centering
\begin{tikzpicture}[
  clique/.style={draw, thick, fill=blue!8, rounded corners},
]
\foreach \k in {0,...,5} {
  \pgfmathsetmacro{\ang}{60*\k}
  \begin{scope}[rotate=\ang]
    \draw[clique] (0.15,-0.55) -- (2.4,-0.75) -- (2.4,0.75) -- (0.15,0.55) -- cycle;
  \end{scope}
}
\fill[black] (0,0) circle (2.2pt);
\node[font=\scriptsize, anchor=north] at (0,-1.6) {shared vertex};
\draw[thin, -{Latex[length=1.5mm]}] (0,-1.4) -- (0,-0.15);
\end{tikzpicture}
\caption{The extremal picture the conjecture allows: $n$ cliques of size $n$
arranged around a single shared vertex, pairwise intersection exactly one.
The conjecture's claim is that the union of any such family --- sharing a
vertex, sharing nothing, or anything between --- always colours with $n$
colours.}
\label{fig:windmill}
\end{figure}

\begin{definition}[Erd\H{o}s--Faber--Lov\'asz conjecture]
For every $n$ and every Erd\H{o}s--Faber--Lov\'asz family $C_1,\dots,C_n$ on
a vertex set $V$, the graph $G$ on $V$ with $u \sim v$ iff $u,v$ lie together
in some $C_i$ has chromatic number at most $n$.
\end{definition}

Kang, Kelly, K\"uhn, Methuku, and Osthus proved this for all sufficiently
large $n$ by the absorption method \cite{KangKellyKuhnMethukuOsthus2021}; an
earlier bound of $\tfrac32 n - 2$ colours, valid for every $n$, is due to
Chang and Lawler \cite{ChangLawler1988}. Neither question is this paper's
subject.

\section{The question a formal statement forces}

A statement of the form ``every family satisfying $P$ has property $Q$'' is
true of every family whenever no family satisfies $P$ at all: the implication
holds vacuously, and nothing about $Q$ has been tested. This is not a remark
about the conjecture --- Chang--Lawler and Kang--Kelly--K\"uhn--Methuku--Osthus
both work with genuine families throughout --- but it is exactly the check a
formal statement must discharge for itself, and the literature's informal
phrasing does not make it visible. A precise statement fixes an ambient
vertex set $V$ and asks for $n$ subsets of size $n$ meeting pairwise in at
most one point \emph{inside that $V$}. If $V$ is too constrained --- if, for
instance, $V$ is taken to have exactly $n$ elements, forcing every $C_i$ to
be all of $V$ --- the pairwise-intersection hypothesis can fail for every
family definable at all, and the conjecture becomes true of that formal
statement for a reason that has nothing to do with graph colouring.

\begin{theorem}[Satisfiability]
\label{thm:sat}
For every $n \ge 1$, there is a vertex set $V$ and an Erd\H{o}s--Faber--Lov\'asz
family $C_1,\dots,C_n$ on $V$ with the $C_i$ pairwise disjoint.
\end{theorem}

\begin{proof}
Take $V = \{1,\dots,n^2\}$ and $C_i = \{(i-1)n+1,\, (i-1)n+2,\, \dots,\, in\}$
for $i=1,\dots,n$: the $i$-th block of $n$ consecutive integers. Each $C_i$
has size $n$, and the blocks partition $V$, so $C_i \cap C_j = \varnothing$
for $i \ne j$ --- in particular $|C_i \cap C_j| = 0 \le 1$.
\end{proof}

\begin{figure}[h]
\centering
\begin{tikzpicture}[
  cell/.style={draw, thick, minimum width=0.55cm, minimum height=0.55cm, font=\tiny},
]
\foreach \i in {0,...,3} {
  \pgfmathtruncatemacro{\shade}{6+18*\i}
  \pgfmathtruncatemacro{\rowlab}{\i+1}
  \foreach \j in {0,...,3} {
    \pgfmathtruncatemacro{\v}{4*\i+\j+1}
    \node[cell, fill=blue!\shade!white] at (\j*0.6, -\i*0.7) {\v};
  }
  \node[font=\scriptsize, anchor=east] at (-0.45,-\i*0.7) {$C_{\rowlab}$};
}
\end{tikzpicture}
\caption{The witness for $n=4$: four disjoint blocks of four consecutive
integers. Every pairwise intersection is empty, so the hypothesis
$|C_i \cap C_j| \le 1$ holds --- with room to spare --- for every $i \ne j$.}
\label{fig:witness}
\end{figure}

\Cref{thm:sat} is deliberately the least interesting family that satisfies
the hypothesis: it makes no use of the shared-vertex configuration in
\Cref{fig:windmill}, which is the case the conjecture's difficulty actually
lives in. That is the point. The theorem is not evidence for the conjecture;
it is the check that the conjecture has non-vacuous content to be evidence
\emph{for}, stated and proved rather than assumed.

\section{Position}

The tight bound --- chromatic number at most $n$, for every $n$ --- is the
theorem of \cite{KangKellyKuhnMethukuOsthus2021}, cited here as the external
result it is and not re-derived. What this note adds is upstream of that
theorem: the hypothesis it quantifies over is realizable at every size, with
an explicit witness, so a formal statement of the conjecture is a claim about
graph colouring and not an empty implication dressed as one.

\section{Verification}

\Cref{thm:sat} is formalized in \Lean{} against Mathlib over an arbitrary
finite vertex type (rather than one artificially sized to match the clique
count), and depends on \texttt{propext}, \texttt{Classical.choice}, and
\texttt{Quot.sound} only. The tight bound of
\cite{KangKellyKuhnMethukuOsthus2021} is recorded as a standing hypothesis in
the same development, attributed rather than discharged: transcribing an
external theorem into a type and proving it are different acts, and the
formalization keeps them visibly different.

\begin{thebibliography}{9}
\bibitem{KangKellyKuhnMethukuOsthus2021} D.~Y.~Kang, T.~Kelly, D.~K\"uhn,
A.~Methuku, and D.~Osthus, \emph{A proof of the Erd\H{o}s--Faber--Lov\'asz
conjecture}, Ann.\ of Math.\ \textbf{198} (2023), 537--618.

\bibitem{ChangLawler1988} W.~I.~Chang and E.~L.~Lawler, \emph{Edge colouring
of hypergraphs and a conjecture of Erd\H{o}s, Faber, Lov\'asz}, Combinatorica
\textbf{8} (1988), 293--295.

\bibitem{Erdos1981} P.~Erd\H{o}s, \emph{On the combinatorial problems which I
would most like to see solved}, Combinatorica \textbf{1} (1981), 25--42.
\end{thebibliography}

