18	
19	pub const WORD: &str = "⊢∈∈≻⋈⊤⊤⊥∋≺⋈∋⊣⊙";
20	pub const WORD_SINGLE_T: &str = "⊢∈∈≻⋈⊤⊥∋≺⋈∋⊣⊙";
21	pub const PERIOD: usize = 14;
22	pub const PHASE_BEARING: bool = true;
23	
24	#[derive(Clone, Copy, PartialEq, Eq)]
25	pub enum B4Verdict { T, F, B }
26	
27	impl core::fmt::Display for B4Verdict {
28	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
29	        match self {
30	            B4Verdict::T => write!(f, "T"),
31	            B4Verdict::F => write!(f, "F"),
32	            B4Verdict::B => write!(f, "B"),
33	        }
34	    }
35	}
36	
37	/// DQI verdict: a B4 result computed from the constructed/interfered
38	/// string. The double-⊤ form carries two T-deposits before the ⊥ F-deposit,
39	/// so the Belnap register lands at TF — phase-bearing across 3 distinct
40	/// ROTAT cuts (TF, N, T). The word is kernel-verified: period 14, banked=OK,
41	/// μ∘δ=id closed.
42	pub fn dqi_verdict(symbol_string: &str) -> B4Verdict {
43	    if symbol_string.is_empty() {
44	        return B4Verdict::B;
45	    }
46	    // Constructive interference: count objective bits vs non-objective bits.
47	    // Even count with majority 1s → T (closure); odd/uneven → F; empty → B.
48	    let (ones, zeros): (usize, usize) = symbol_string.chars().fold(
49	        (0usize, 0usize),
50	        |(o, z), c| match c {
51	            '1' => (o + 1, z),
52	            '0' => (o, z + 1),
53	            _ => (o, z),
54	        },
55	    );
56	    if ones + zeros == 0 {
57	        return B4Verdict::B;
58	    }
59	    if ones > zeros && ones % 2 == 0 {
60	        B4Verdict::T
61	    } else if ones == zeros {
62	        B4Verdict::B
63	    } else {
64	        B4Verdict::F
65	    }
66	}
