            sprintln!("  fdeRestrict_trans holds: {}", direct == via_j);
        }
        "report" => {
            sprintln!("── FDE(n) Tower Descent Report ──");
            sprintln!("  source: Imscribing/Paraconsistent/FDEAsymptotic.lean");
            sprintln!("  FDEN n = Bot | Mid(Fin n) | Top, n+2 truth values");
