30	// find r = ord_a(N). N is prime iff r | (N-1) for all co-prime bases.
31	pub fn oneshot_verdict(n_str: &str) -> B4Verdict {
32	    let t = {
33	        let bytes = n_str.as_bytes();
34	        let mut i = 0;
35	        while i + 1 < bytes.len() && bytes[i] == b'0' { i += 1; }
36	        String::from(&n_str[i..])
37	    };
38	    if t.is_empty() || t == "0" { return B4Verdict::B; }
39	    if t == "1" { return B4Verdict::B; }
40	    if let Ok(n) = t.parse::<num_bigint::BigUint>() {
41	        if n <= num_bigint::BigUint::from(1u32) { return B4Verdict::B; }
42	    }
43	    let trimmed = t.trim_start_matches('0');
44	    if trimmed.is_empty() || trimmed == "1" { return B4Verdict::B; }
