47	    if let Ok(n) = trimmed.parse::<u64>() {
48	        if n < 3 { return B4Verdict::B; }
49	        let bases = [2u64, 3, 5, 7, 11, 13];
50	        for &a in &bases {
51	            if a % n == 0 { continue; }
52	            if let Some(r) = crate::winding_period::winding_order(a, n) {
53	                if (n - 1) % r != 0 { return B4Verdict::F; }
54	            } else {
