99	// Miller-Rabin primality test for BigUint.
100	fn is_prime_big(n: &BigUint) -> bool {
101	    if n < &BigUint::from(2u32) { return false; }
102	    let two = BigUint::from(2u32);
103	    let three = BigUint::from(3u32);
104	    if n == &two || n == &three { return true; }
105	    if n % 2u32 == BigUint::zero() { return false; }
106	
107	    // write n-1 = d * 2^s with d odd
108	    let n_minus_1 = n - 1u32;
109	    let mut s: u32 = 0;
110	    let mut d = n_minus_1.clone();
111	    let two_b = BigUint::from(2u32);
112	    while &d % &two_b == BigUint::zero() {
113	        d /= 2u32;
114	        s += 1;
115	    }
116	
117	    // Deterministic bases for various ranges; fall back to several small primes.
118	    let max_deterministic: BigUint = BigUint::from_str("33170440646798834559697582").unwrap();
119	    let bases: Vec<BigUint> = if n < &max_deterministic {
120	        // Single base 2 is deterministic for this range
121	        alloc::vec![BigUint::from(2u32)]
122	    } else {
123	        // Several small bases — deterministic for most practical sizes
124	        let small: [u32; 7] = [2, 3, 5, 7, 11, 13, 17];
125	        small.iter().map(|&b| BigUint::from(b) % n).collect()
126	    };
127	
128	    for a in &bases {
129	        if a.is_zero() { continue; }
130	        let mut x = a.modpow(&d, n);
131	        if x == BigUint::one() || x == n_minus_1 { continue; }
132	        let mut cont = false;
133	        for _ in 1..s {
134	            x = (&x * &x) % n;
135	            if x == n_minus_1 { cont = true; break; }
136	        }
137	        if !cont { return false; }
138	    }
139	    true
140	}
