142	// Brent's cycle detection with fold/kiss topology (BigUint, arbitrary length)
143	fn brent_factor_big(n: &BigUint) -> Option<BigUint> {
144	    let two = BigUint::from(2u32);
145	    if n % 2u32 == BigUint::zero() { return Some(two.clone()); }
146	    if n.is_one() { return None; }
147	
148	    // Seed c from the word's 4 distinct landing states
149	    let c_candidates: [u64; 4] = [3, 7, 11, 17];
150	    let n_mod_97 = (n % BigUint::from(97u32)).to_u64().unwrap_or(0);
151	
152	    for (i, &base_c) in c_candidates.iter().enumerate() {
153	        // c = (base_c + (n%97)*(i+1)) % n, ensure >= 1
154	        let c_raw = base_c.wrapping_add((n_mod_97 as u64).wrapping_mul(i as u64 + 1)) % 1_000_000;
155	        let c = BigUint::from(if c_raw == 0 { 1u64 } else { c_raw });
156	
157	        let x_init = BigUint::from(2u64 + (n_mod_97 % 95));
158	        let mut x: BigUint = x_init.clone();
159	        let m: u64 = 128;
160	        let mut power: u64 = 1;
161	        #[allow(unused_assignments)]
162	        let mut y: BigUint = x.clone();
163	
164	        while power < 1_000_000 {
165	            // λ = power steps
166	            let mut step: u64 = 0;
167	            while step < power {
168	                x = brent_f(&x, &c, n);
169	                step += 1;
170	            }
171	            y = x.clone();
172	            // μ = power steps, compare to stored
173	            let mut j: u64 = 0;
174	            let upper = power.min(m);
175	            while j < upper {
176	                x = brent_f(&x, &c, n);
177	                let d = if x > y { &x - &y } else { &y - &x };
178	                let g = big_gcd(d, n.clone());
179	                if !g.is_one() && g != *n { return Some(g); }
180	                j += 1;
181	            }
182	            power = match power.checked_mul(2) {
183	                Some(p) => p,
184	                None => break,
185	            };
186	        }
187	    }
188	    None
189	}
