191	fn factor_recursive_big(mut n: BigUint) -> Vec<BigUint> {
192	    let mut factors: Vec<BigUint> = Vec::new();
193	    let two = BigUint::from(2u32);
194	    while &n % &two == BigUint::zero() {
195	        factors.push(two.clone());
196	        n /= 2u32;
197	    }
198	    let mut stack: Vec<BigUint> = Vec::new();
199	    if !n.is_one() { stack.push(n); }
200	    while let Some(m) = stack.pop() {
201	        if m.is_one() { continue; }
202	        if is_prime_big(&m) { factors.push(m); continue; }
203	        if let Some(f) = brent_factor_big(&m) {
204	            let g = &m / &f;
205	            if f >= g {
206	                stack.push(f);
207	                stack.push(g);
208	            } else {
209	                stack.push(g);
210	                stack.push(f);
211	            }
212	        } else {
213	            factors.push(m); // conservative: treat as prime
214	        }
215	    }
216	    factors.sort_unstable();
217	    factors
