            )
        } else {
            "No repair found\n".to_string()
        }
    }
}

pub fn repair_main(args: &[&str]) -> String {
    let engine = RepairEngine::new();

    if args.is_empty() {
        return "USAGE:\n\
                 repair <program>\n\
                 repair <proof>\n\
                 repair <Lean theorem>\n\
                 repair <invariant>\n\
                 \n\
                 Repair types searched:\n\
                 1. Insertion\n\
                 2. Deletion\n\
                 3. Substitution\n\
                 4. Permutation\n\
                 5. Rotation\n\
                 6. Local rewrite\n\
                 7. Primitive promotion\n\
                 \n\
                 Cost function:\n\
                 cost = α(edit_distance) + β(ΔS) + γ(tier_change) + δ(new_assumptions)\n\
                 \n\
                 Example:\n\
                 repair ⊢⊙∈⊤⊥∋⊡⊣\n"
            .to_string();
    }

    let artifact = args[0];
    let artifact_type = args.get(1).unwrap_or(&"program");

    let result = engine.repair(artifact, artifact_type);

    format!(
        "REPAIR ANALYSIS\n\
         =============\n\
         Original artifact: {}\n\
         Artifact type: {}\n\
         Error diagnosed: {}\n\
         \n\
         Repairs found: {}\n\
         \n",
        result.original,
        artifact_type,
        result.error_type,
        result.repairs.len()
    ) + 
    if result.repairs.is_empty() {
        "No valid repairs found in search space.\n"
    } else {
        "TOP REPAIRS (ranked by cost):\n\n"
    } + &result.repairs.iter()
        .take(5)
