1	// rsa_decrypter.rs — RSA Decrypter via Baby-Step Giant-Step Period Finding
2	//
3	// The ob3ect glyph word: ⊢⊣∈≻⊤≺⊥∋⋈⊞≻⋈⊙⊤⊡⊣
4	//
5	// ONESHOT PRINCIPLE: Construct the decryption inside its own fixed-point closure.
6	// For a given ciphertext C, modulus N, and private exponent d,
7	// the winding period r is found via Baby-Step Giant-Step (BSGS).
8	// The private descent C^d mod N is the reverse morphism closing the loop.
9	//
10	// Phase 2 (Frobenius):
11	//   ∈ Period Finding Fork → Baby-Step Lattice (forward) + Giant-Step Search (reverse)
12	//   ∋ Winding Period Resolution → Minimal Period r (Frobenius verdict T)
13	//
14	// The BSGS algorithm finds the minimal r such that a^r ≡ 1 (mod N)
15	// where a is the base (typically the ciphertext or a generator).
16	// Then d ≡ e^(-1) mod r gives the private exponent.
17	// Actually for RSA decryption: M = C^d mod N where d is the private exponent.
18	// The period finding is for the multiplicative group order φ(N) or the
19	// order of C modulo N. BSGS finds r = ord_N(C), then d*e ≡ 1 (mod r).
20	//
21	// Implementation uses num_bigint::BigUint for arbitrary precision.
22	
23	#![allow(dead_code)]
24	extern crate alloc;
25	
26	use crate::sprintln;
27	use alloc::string::String;
28	use alloc::collections::BTreeMap;
29	use num_bigint::BigUint;
30	use num_traits::{One, Zero, ToPrimitive};
31	use core::str::FromStr;
32	
33	/// Trim leading zeros from a decimal string
34	fn trim(s: &str) -> String {
35	    let bytes = s.as_bytes();
36	    let mut i = 0;
37	    while i + 1 < bytes.len() && bytes[i] == b'0' { i += 1; }
38	    String::from(&s[i..])
39	}
40	
41	/// Parse a decimal string into BigUint
42	fn parse_big(s: &str) -> Option<BigUint> {
43	    let t = trim(s);
44	    if t.is_empty() { return None; }
45	    BigUint::from_str(&t).ok()
46	}
47	
48	/// BigUint GCD
49	fn big_gcd(mut a: BigUint, mut b: BigUint) -> BigUint {
50	    while !b.is_zero() {
51	        let t = b.clone();
52	        b = &a % &b;
53	        a = t;
54	    }
55	    a
56	}
57	
58	/// Modular exponentiation: base^exp mod modulus
59	fn mod_pow(base: &BigUint, exp: &BigUint, modulus: &BigUint) -> BigUint {
60	    let mut result = BigUint::one();
61	    let mut base = base % modulus;
62	    let mut exp = exp.clone();
63	    while !exp.is_zero() {
64	        if &exp & BigUint::one() == BigUint::one() {
65	            result = (result * &base) % modulus;
66	        }
67	        base = (&base * &base) % modulus;
68	        exp >>= 1;
69	    }
70	    result
71	}
72	
73	/// Baby-Step Giant-Step to find the minimal period r such that base^r ≡ 1 (mod n)
74	/// Returns the period r, or None if not found within sqrt(n) steps
75	fn bsgs_period(base: &BigUint, n: &BigUint) -> Option<BigUint> {
76	    if n <= &BigUint::one() { return None; }
77	    if base % n == BigUint::zero() { return None; }
78	    
79	    // m = ceil(sqrt(n))
80	    let n_bits = n.bits();
81	    let m_bits = (n_bits + 1) / 2;
82	    let m = BigUint::one() << m_bits;
83	    let m_usize: usize = m.to_usize().unwrap_or(1000000).min(1000000); // cap for memory
84	    
85	    // Baby steps: base^j for j = 0..m
86	    let mut baby_steps = BTreeMap::new();
87	    let mut cur = BigUint::one();
88	    for j in 0..m_usize {
89	        baby_steps.insert(cur.clone(), j);
90	        cur = (&cur * base) % n;
91	    }
92	    
93	    // Giant step factor: base^(-m) mod n
94	    // Compute base^m first, then its modular inverse
95	    let base_m = mod_pow(base, &BigUint::from(m_usize), n);
96	    let inv_base_m = mod_inverse(&base_m, n)?;
97	    
98	    // Giant steps: search for collision
99	    cur = BigUint::one();
100	    for i in 0..m_usize {
101	        if let Some(&j) = baby_steps.get(&cur) {
102	            let r = BigUint::from(i * m_usize + j);
103	            if r > BigUint::zero() && mod_pow(base, &r, n) == BigUint::one() {
104	                return Some(r);
105	            }
106	        }
107	        cur = (&cur * &inv_base_m) % n;
108	    }
109	    None
110	}
111	
112	/// Extended Euclidean Algorithm for modular inverse
113	fn egcd(a: &BigUint, b: &BigUint) -> (BigUint, BigUint, BigUint) {
114	    if b.is_zero() {
115	        return (a.clone(), BigUint::one(), BigUint::zero());
116	    }
117	    let (g, x1, y1) = egcd(b, &(a % b));
118	    let x = y1.clone();
119	    let y = &x1 - &(a / b) * &y1;
120	    (g, x, y)
121	}
122	
123	fn mod_inverse(a: &BigUint, n: &BigUint) -> Option<BigUint> {
124	    let (g, x, _) = egcd(a, n);
125	    if g != BigUint::one() { return None; }
126	    let mut inv = x % n;
127	    if inv == BigUint::zero() { inv = n.clone(); }
128	    Some(inv)
129	}
130	
131	/// Compute private exponent d from public exponent e and period r
132	/// d ≡ e^(-1) mod r
133	fn compute_private_exponent(e: &BigUint, r: &BigUint) -> Option<BigUint> {
134	    mod_inverse(e, r)
135	}
136	
137	/// Decrypt: M = C^d mod N
138	fn decrypt(ciphertext: &BigUint, d: &BigUint, n: &BigUint) -> BigUint {
139	    mod_pow(ciphertext, d, n)
140	}
141	
142	/// The ob3ect glyph word for RSA Decrypter
143	pub const GLYPH_WORD: &str = "⊢⊣∈≻⊤≺⊥∋⋈⊞≻⋈⊙⊤⊡⊣";
144	
145	/// Main decryption function implementing the ob3ect flow
146	pub fn rsa_decrypt(c_str: &str, n_str: &str, e_str: &str) -> Option<String> {
147	    let c = parse_big(c_str)?;
148	    let n = parse_big(n_str)?;
149	    let e = parse_big(e_str)?;
150	    
151	    if n <= &BigUint::one() { return None; }
152	    if c >= n { return None; }
153	    
154	    // Step 1: Find the winding period r = ord_n(C) via BSGS (∈/∋ phase)
155	    sprintln!("∈ Period Finding Fork: BSGS search for r = ord_N(C)...");
156	    let r = bsgs_period(&c, &n)?;
157	    sprintln!("∋ Winding Period Resolution: r = {} ({} digits)", r, r.to_str_radix(10).len());
158	    
159	    // Step 2: Compute private exponent d ≡ e^(-1) mod r (⊞ phase - dialetheic key state)
160	    sprintln!("⊞ Dialetheic Key State: computing d ≡ e^(-1) mod r...");
161	    let d = compute_private_exponent(&e, &r)?;
162	    sprintln!("  d = {} ({} digits)", d, d.to_str_radix(10).len());
163	    
164	    // Step 3: Decrypt M = C^d mod N (≻⋈ descent + ⊙ identity + ⊤ verification)
165	    sprintln!("≻⋈ Private Descent: C^d mod N...");
166	    let m = decrypt(&c, &d, &n);
167	    sprintln!("⊙ Identity: C^d ≡ {} (mod N)", m);
168	    sprintln!("⊤ Closure Verification: M^e ≡ C (mod N) = {}", 
169	        if mod_pow(&m, &e, &n) == c { "PASS" } else { "FAIL" });
170	    
171	    // Step 4: Fix the plaintext (⊡)
172	    sprintln!("⊡ Plaintext Record: {} ({} digits)", m, m.to_str_radix(10).len());
173	    
174	    Some(m.to_str_radix(10))
175	}
