    let (g, x, _) = egcd(&a_i, &n_i);
    if g != BigInt::one() { return None; }
    let mut inv = &x % &n_i;
    if inv < BigInt::zero() { inv += &n_i; }
    if inv.is_zero() { inv = n_i; }
    inv.to_biguint()
}

