217	    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
218	        let align = layout.align();
219	        let size  = layout.size();
220	        // A zero-size request must never fail. With the heap nearly full the
221	        // alignment round-up alone can push past `end`, and returning null for a
222	        // zero-byte allocation surfaced as "memory allocation of 0 bytes failed"
223	        // — a panic that named a size nobody had asked for. Hand back a dangling
224	        // but correctly aligned pointer, which is what a zero-size allocation is.
225	        if size == 0 {
226	            return align as *mut u8;
227	        }
228	        loop {
229	            let cur     = self.next.load(Ordering::Relaxed);
230	            let aligned = (cur + align - 1) & !(align - 1);
231	            let new     = aligned + size;
232	            // Null here reaches `alloc_error` below, which reports the real
233	            // layout. Nothing is printed at this point so a caller that
234	            // handles the null itself is not made to look like a crash.
235	            if new > self.end.load(Ordering::Relaxed) { return core::ptr::null_mut(); }
236	            if self.next.compare_exchange_weak(
237	                cur, new, Ordering::Relaxed, Ordering::Relaxed,
238	            ).is_ok() {
239	                return aligned as *mut u8;
240	            }
241	        }
242	    }
