245	        // bump pointer back. Catches the transient Vecs of a forward pass.
246	        let end = ptr as usize + layout.size();
247	        let _ = self.next.compare_exchange(
248	            end, ptr as usize, Ordering::Relaxed, Ordering::Relaxed,
