117	\node[box, fill=green!6] (R) at (6,0) {$\{0,1,\dots,\Sigma\}$ \\[2pt] $\Sigma+1$ integers};
118	\draw[arr] (P) -- node[above, font=\small]{$f$, injective} (R);
119	\node[below=0.3cm of P, font=\footnotesize, text width=3.6cm, align=center]
120	  {every subset};
121	\node[below=0.3cm of R, font=\footnotesize, text width=3.6cm, align=center]
122	  {every reachable sum};
123	\end{tikzpicture}
