1	//! Lattice cycling and weight flow over an IMASM word, in the kernel.
2	//!
3	//! A word is a ring and ROTAT is the cyclic shift, so every rotation is the
4	//! same object. The verdict and the topology hold across the whole orbit; the
5	//! FINAL REGISTER does not. That makes the phase the only handle on where a
6	//! word comes to rest, and `cycle_report` prints the map from cut to landing
7	//! register so the handle can be read rather than guessed.
8	//!
9	//! `weight_report` answers the other half. The trilattice machine holds each
10	//! open fork as a set and closes it with a union, so a finished walk knows
11	//! WHICH base values were touched and nothing else: not how many times, not by
12	//! which arm, not whether a value reached the end or was destroyed and restored
13	//! on the way. This walks the same rules while counting, so the movement is
14	//! visible. Weight banked in a frame survives a clear that empties the
15	//! register; weight left in the open does not.
16	//!
17	//! The lift of OR to weights is MAX, not sum. Adding would count each deposit
18	//! twice, once landing in the register and again when its frame closed; under
19	//! max the fuse RESTORES what a clear destroyed and leaves the rest alone, and
20	//! at weights zero and one the accounting reduces to the set semantics exactly.
21	//!
22	//! Two movements carry no weight at all and are reported because they are
23	//! otherwise invisible in a final register:
24	//!
25	//!   SEED   AFWD and IMSCRIB put T into an empty register directly, so a walk
26	//!          can land in T having carried nothing
27	//!   INERT  after IFIX every token but IFIX and IMSCRIB is a no-op, so a word
28	//!          can be almost entirely inert
29	
30	
31	/// The reports were written straight to the kernel console with `sprintln!`,
32	/// which is why the host `ask` binary could not use them. They build a String
33	/// now and the kernel prints it; `sw!` is the one-line shim that made the move
34	/// mechanical rather than a rewrite.
35	macro_rules! sw {
36	    ($o:expr) => {{ $o.push('\n'); }};
37	    ($o:expr, $($t:tt)*) => {{
38	        use core::fmt::Write as _;
39	        let _ = write!($o, $($t)*);
40	        $o.push('\n');
41	    }};
42	}
43	
44	use alloc::string::String;
45	use alloc::vec::Vec;
46	use alloc::format;
47	use crate::imasm16_3::{parse_glyph_word, run_word_register, tri_ancestral_verdict, Token16_3};
48	
49	
50	/// Bring a word onto the current alphabet before the core reads it.
51	///
52	/// The retired spellings are still in every stored word and in anything copied
53	/// out of an older report, and the tensor forms turn up where a fork and a fuse
54	/// were written as ⊗ and ⊕. Translating is what lets those load; dropping them
55	/// would read the word as shorter than it is and change its verdict.
56	pub fn normalize(word: &str) -> String {
57	    let mut out = String::new();
58	    for c in word.chars() {
59	        match c {
60	            '◇' | '⊗' => out.push('∈'),
61	            '●' | '⊕' => out.push('∋'),
62	            '=' | '═' => out.push('⋈'),
63	            '+' => out.push('⊤'),
64	            '×' => out.push('⊥'),
65	            '¬' => out.push('⊡'),
66	            c if c.is_whitespace() => {}
67	            c => out.push(c),
68	        }
69	    }
70	    out
71	}
72	
73	fn render(steps: &[Token16_3]) -> String {
74	    let mut s = String::new();
75	    for t in steps { s.push(t.glyph()); }
76	    s
77	}
78	
79	/// Walk the orbit and report where each cut lands.
80	pub fn cycle_report(word: &str) -> String {
81	    let mut out = String::new();
82	    let steps = parse_glyph_word(&normalize(word));
83	    let n = steps.len();
84	    if n == 0 {
85	        sw!(out, "  no IMASM glyphs in that word");
86	        return out;
87	    }
88	    sw!(out, "word   : {}   period {}", render(&steps), n);
89	    sw!(out, "   {:>3}  {:<6} {:<8} word", "k", "final", "verdict");
90	
91	    let mut finals: Vec<(String, usize)> = Vec::new();
92	    for k in 0..n {
93	        let mut rot: Vec<Token16_3> = Vec::with_capacity(n);
94	        for i in 0..n { rot.push(steps[(i + k) % n]); }
95	        let reg = run_word_register(&rot);
96	        let (v, _) = tri_ancestral_verdict(&rot);
97	        sw!(out, "   {:>3}  {:<6} {:<8} {}", k, reg, v, render(&rot));
98	        finals.push((reg, k));
99	    }
100	
101	    // The map the whole thing exists for: which cut lands you where.
102	    sw!(out, "");
103	    sw!(out, "  landing register by cut:");
104	    let mut seen: Vec<String> = Vec::new();
105	    for (reg, _) in finals.iter() {
106	        if !seen.iter().any(|s| s == reg) { seen.push(reg.clone()); }
107	    }
108	    for reg in seen.iter() {
109	        let mut ks = String::new();
110	        for (r, k) in finals.iter() {
111	            if r == reg {
112	                if !ks.is_empty() { ks.push_str(", "); }
113	                ks.push_str(&format!("{}", k));
114	            }
115	        }
116	        sw!(out, "    {:<6} at k = {}", reg, ks);
117	    }
118	    let distinct = seen.len();
119	    if distinct == 1 {
120	        sw!(out, "  final register is INVARIANT under ROTAT here");
121	    } else {
122	        sw!(out, "  final register is PHASE-BEARING: {} distinct landings", distinct);
123	    }
124	    out
125	}
126	
127	
128	/// FRAMES — which readings survive rotation and which are artifacts of the cut.
129	///
130	/// A word is a ring. We evaluate ONE cut of it and take what we see there for a
131	/// property of the word, but every rotation is the same object and every frame is
132	/// equally available to be read. So a reported quantity is one of two things, and
133	/// the report must say which:
134	///
135	///   INVARIANT   true of the word — it reads the same from every frame
136	///   FRAME-BOUND it reads the cut, not the word; quoting it without the frame is
137	///               quoting an accident of where the ring was opened
138	///
139	/// This walks the whole orbit and partitions the readings. Anything landing in the
140	/// second column is still real — it is just a fact about a frame, and the frame has
141	/// to travel with it.
142	pub fn frames_report(word: &str) -> String {
143	    let mut out = String::new();
144	    let steps = parse_glyph_word(&normalize(word));
145	    let n = steps.len();
146	    if n == 0 {
147	        sw!(out, "  no IMASM glyphs in that word");
148	        return out;
149	    }
150	    sw!(out, "word   : {}   period {}   ({} frames, all equally readable)", render(&steps), n, n);
151	
152	    let mut verdicts: Vec<char> = Vec::new();
153	    let mut finals: Vec<String> = Vec::new();
154	    let mut firsts: Vec<char> = Vec::new();
155	    for k in 0..n {
156	        let mut rot: Vec<Token16_3> = Vec::with_capacity(n);
157	        for i in 0..n { rot.push(steps[(i + k) % n]); }
158	        let (v, _) = tri_ancestral_verdict(&rot);
159	        verdicts.push(v);
160	        finals.push(run_word_register(&rot));
161	        firsts.push(rot[0].glyph());
162	    }
163	    let uniq_v = {
164	        let mut u: Vec<char> = Vec::new();
165	        for v in verdicts.iter() { if !u.contains(v) { u.push(*v); } }
166	        u
167	    };
168	    let uniq_f = {
169	        let mut u: Vec<String> = Vec::new();
170	        for f in finals.iter() { if !u.iter().any(|x| x == f) { u.push(f.clone()); } }
171	        u
172	    };
173	    let uniq_first = {
174	        let mut u: Vec<char> = Vec::new();
175	        for c in firsts.iter() { if !u.contains(c) { u.push(*c); } }
176	        u
177	    };
178	
179	    sw!(out, "");
180	    sw!(out, "  INVARIANT — true of the word, readable from any frame:");
181	    sw!(out, "    period                {}", n);
182	    sw!(out, "    glyph multiset        {} distinct over {} positions", {
183	        let mut u: Vec<char> = Vec::new();
184	        for t in steps.iter() { let g = t.glyph(); if !u.contains(&g) { u.push(g); } }
185	        u.len()
186	    }, n);
187	    if uniq_v.len() == 1 {
188	        sw!(out, "    verdict               {}", uniq_v[0]);
189	    }
190	    sw!(out, "    ring transitions      counted with the closing edge, so rotation cannot move them");
191	
192	    sw!(out, "");
193	    sw!(out, "  FRAME-BOUND — reads the cut, and must be quoted with it:");
194	    if uniq_v.len() > 1 {
195	        sw!(out, "    verdict               {} distinct over the orbit — NOT a property of the word", uniq_v.len());
196	    }
197	    sw!(out, "    final register        {} distinct landing(s)", uniq_f.len());
198	    for reg in uniq_f.iter() {
199	        let mut ks = String::new();
200	        for (k, f) in finals.iter().enumerate() {
201	            if f == reg {
202	                if !ks.is_empty() { ks.push_str(", "); }
203	                ks.push_str(&format!("{}", k));
204	            }
205	        }
206	        sw!(out, "      {:<6} at k = {}", reg, ks);
207	    }
208	    sw!(out, "    opening glyph         {} distinct — every frame opens on a different mark", uniq_first.len());
209	    sw!(out, "    absolute position     any row/tier/parity reading; one rotation moves every value");
210	
211	    sw!(out, "");
212	    if uniq_f.len() == 1 {
213	        sw!(out, "  This word is FRAME-FREE in its landing: every cut comes to rest in the same");
214	        sw!(out, "  register, so the evaluated frame carries no privilege over the others.");
215	    } else {
216	        sw!(out, "  This word is PHASE-BEARING: {} of its {} frames disagree about where it rests.", uniq_f.len(), n);
217	        sw!(out, "  The frame you evaluated is one of them and is not the word's own answer.");
218	    }
219	    out
220	}
221	
222	/// Opcode-to-opcode transitions counted ON THE RING.
223	///
224	/// A word is a cycle and ROTAT is the cyclic shift, so a word of length n has n
225	/// transitions, not n-1. The one a linear read drops is the wrap from the last
226	/// opcode back to the first, and in IMASM that is overwhelmingly TANCH -> VINIT:
227	/// the anchor returning to the source. Across k programs a linear read loses
228	/// exactly k such edges, and a table built without them can show a rule as
229	/// universal that the closing edges break.
230	pub fn transitions_report(word: &str) -> String {
231	    let mut out = String::new();
232	    let steps = parse_glyph_word(&normalize(word));
233	    let n = steps.len();
234	    if n == 0 { sw!(out, "  no IMASM glyphs in that word"); return out; }
235	    sw!(out, "word   : {}   length {}", render(&steps), n);
236	    sw!(out, "  ring transitions   : {}", n);
237	    sw!(out, "  linear would give  : {}   (drops the closing edge)", n - 1);
238	    sw!(out, "  closing edge       : {} -> {}",
239	              steps[n - 1].glyph(), steps[0].glyph());
240	    sw!(out, "");
241	    // count them, most frequent first, without allocating a map
242	    let mut seen: Vec<((char, char), u32)> = Vec::new();
243	    for i in 0..n {
244	        let key = (steps[i].glyph(), steps[(i + 1) % n].glyph());
245	        if let Some(e) = seen.iter_mut().find(|e| e.0 == key) { e.1 += 1; }
246	        else { seen.push((key, 1)); }
247	    }
248	    seen.sort_by(|a, b| b.1.cmp(&a.1));
249	    sw!(out, "  transitions:");
250	    for ((a, b), c) in seen.iter() {
251	        sw!(out, "    {} -> {}   {}", a, b, c);
252	    }
253	    sw!(out, "");
254	    sw!(out, "  Anything read from ABSOLUTE position on a ring measures the cut,");
255	    sw!(out, "  not the word: matrix rows, tetraktys tiers, odd against even.");
256	    sw!(out, "  One rotation moves every value into a different row.");
257	    out
258	}
259	
260	/// Was anything counted, then cleared with nothing banked behind it?
261	///
262	/// AREV empties the register and leaves open frames alone, so a result fused
263	/// back to depth zero is exposed to the next reversal, while the same result
264	/// held one level up survives it. A program that establishes something, then
265	/// reverses, then bounds must open the region that will HOLD the result before
266	/// the region that COMPUTES it, and close them in that order.
267	/// What the banking walk found. Separated from the printing so a caller can
268	/// test a word instead of reading about it -- `insert` sweeps hundreds of
269	/// candidates and needs the verdict, not the paragraph. One walk, two callers.
270	pub struct Banked {
271	    pub exposed: Vec<(usize, char, u32)>,
272	    pub live_clears: u32,
273	    pub deposits: u32,
274	    pub inert: u32,
275	    pub reg: [u32; 4],
276	}
277	
278	impl Banked {
279	    /// Held across every clear that actually fired. Vacuous words are not OK:
280	    /// nothing was ever at risk, so nothing was held.
281	    pub fn holds(&self) -> bool { self.exposed.is_empty() && self.live_clears > 0 }
282	    pub fn vacuous(&self) -> bool { self.exposed.is_empty() && self.live_clears == 0 }
283	}
284	
285	pub fn banked_walk(word: &str) -> Option<Banked> {
286	    let steps = parse_glyph_word(&normalize(word));
287	    if steps.is_empty() { return None; }
288	    let mut reg = [0u32; 4];
289	    let mut frames: Vec<[u32; 4]> = Vec::new();
290	    let mut fixed = false;
291	    let mut exposed: Vec<(usize, char, u32)> = Vec::new();
292	    let mut live_clears = 0u32;
293	    let mut inert = 0u32;
294	    let mut deposits = 0u32;
295	
296	    for (i, t) in steps.iter().enumerate() {
297	        if fixed && !matches!(t, Token16_3::Ifix | Token16_3::Imscrib) { inert += 1; continue; }
298	        match t {
299	            Token16_3::Fsplit3 => frames.push([0; 4]),
300	            Token16_3::Ffuse3 => {
301	                if let Some(closed) = frames.pop() {
302	                    for j in 0..4 {
303	                        if closed[j] > reg[j] { reg[j] = closed[j]; }
304	                        if let Some(o) = frames.last_mut() {
305	                            if closed[j] > o[j] { o[j] = closed[j]; }
306	                        }
307	                    }
308	                }
309	            }
310	            Token16_3::Arev | Token16_3::Vinit => {
311	                let lost: u32 = reg.iter().sum();
312	                let banked: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
313	                if lost > 0 {
314	                    live_clears += 1;
315	                    if banked == 0 { exposed.push((i + 1, t.glyph(), lost)); }
316	                }
317	                reg = [0; 4];
318	                if matches!(t, Token16_3::Vinit) { frames.clear(); }
319	            }
320	            Token16_3::Ifix => fixed = true,
321	            _ => {
322	                let touched: &[usize] = match t {
323	                    Token16_3::Evalt => &[0],
324	                    Token16_3::Evalf => &[1],
325	                    Token16_3::Evali => &[2, 3],
326	                    _ => &[],
327	                };
328	                if !touched.is_empty() { deposits += 1; }
329	                for &j in touched {
330	                    reg[j] += 1;
331	                    if let Some(f) = frames.last_mut() { f[j] += 1; }
332	                }
333	            }
334	        }
335	    }
336	
337	    Some(Banked { exposed, live_clears, deposits, inert, reg })
338	}
339	
340	pub fn banked_report(word: &str) -> String {
341	    let mut out = String::new();
342	    let steps = parse_glyph_word(&normalize(word));
343	    let b = match banked_walk(word) {
344	        Some(b) => b,
345	        None => { sw!(out, "  no IMASM glyphs in that word"); return out; }
346	    };
347	    let (exposed, live_clears, deposits, inert, reg) =
348	        (b.exposed, b.live_clears, b.deposits, b.inert, b.reg);
349	
350	    sw!(out, "word   : {}", render(&steps));
351	    if exposed.is_empty() && live_clears == 0 {
352	        // Passing because nothing was ever at risk is not the same as passing
353	        // because the frame held.
354	        sw!(out, "  VACUOUS — no clear ever fired against a live register");
355	        sw!(out, "    {} deposit(s), {} step(s) inert after a fixation", deposits, inert);
356	    } else if exposed.is_empty() {
357	        sw!(out, "  OK — weight survived {} live clear(s) by being banked", live_clears);
358	        // The second, independent fact. Banking asks whether a frame was open
359	        // at the clear; surplus asks where the splits fell between deposits of
360	        // the same value. A word can bank correctly and still lose a count.
361	        let mut surplus = 0u32;
362	        for j in 0..4 { if reg[j] > 1 { surplus += reg[j] - 1; } }
363	        if surplus > 0 {
364	            sw!(out, "    up to {} unit(s) of repeat deposit may be flattened by a", surplus);
365	            sw!(out, "    fold between sibling regions: the fold keeps the larger,");
366	            sw!(out, "    not the sum. Deposits in ONE region keep both.");
367	        }
368	    } else {
369	        let total: u32 = exposed.iter().map(|e| e.2).sum();
370	        sw!(out, "  {} unit(s) cleared with nothing banked behind them:", total);
371	        for (step, g, w) in exposed.iter() {
372	            sw!(out, "    step {} {} cleared {} with nothing behind it", step, g, w);
373	        }
374	        sw!(out, "  open the region that HOLDS the result before the region that");
375	        sw!(out, "  COMPUTES it, and close them in that order.");
376	    }
377	    out
378	}
379	
380	/// Every single-glyph insertion that turns an exposed word into one that holds.
381	///
382	/// A word that loses weight is not usually rewritten; it is repaired, and the
383	/// repair is almost always one glyph in the right place. Rather than reason
384	/// about which, this walks all twelve glyphs at every position and reports the
385	/// ones that hold. The search is small -- twelve times length-plus-one -- and
386	/// exact, so there is nothing to infer.
387	pub fn insert_report(word: &str) -> String {
388	    let mut out = String::new();
389	    let steps = parse_glyph_word(&normalize(word));
390	    if steps.is_empty() { sw!(out, "  no IMASM glyphs in that word"); return out; }
391	    let base = render(&steps);
392	    let n = steps.len();
393	
394	    sw!(out, "word   : {}   length {}", base, n);
395	    match banked_walk(&base) {
396	        Some(b) if b.holds()   => { sw!(out, "  already holds — nothing to repair"); return out; }
397	        Some(b) if b.vacuous() => sw!(out, "  vacuous: no clear ever fired, so nothing is at risk"),
398	        Some(b) => {
399	            let lost: u32 = b.exposed.iter().map(|e| e.2).sum();
400	            sw!(out, "  exposed: {} unit(s) cleared with nothing banked", lost);
401	        }
402	        None => return out,
403	    }
404	
405	    let glyphs = ['⊢', '⊙', '∈', '∋', '⊤', '⊥', '≻', '≺', '⋈', '⊞', '⊡', '⊣'];
406	    let chars: Vec<char> = base.chars().collect();
407	
408	    // Distinct words, not distinct sites. Inserting a glyph beside an identical
409	    // one yields the same word from two positions, and counting both would
410	    // report a repair twice and overstate how many ways out there are.
411	    let mut seen: Vec<String> = Vec::new();
412	    let mut tried = 0u32;
413	
414	    sw!(out, "  insertions that hold:");
415	    for pos in 0..=n {
416	        for g in glyphs.iter() {
417	            let mut cand = String::new();
418	            for (k, c) in chars.iter().enumerate() {
419	                if k == pos { cand.push(*g); }
420	                cand.push(*c);
421	            }
422	            if pos == n { cand.push(*g); }
423	            if seen.iter().any(|w| w == &cand) { continue; }
424	            tried += 1;
425	            if let Some(b) = banked_walk(&cand) {
426	                if b.holds() {
427	                    sw!(out, "    {} at {:>2}   {}", g, pos, cand);
428	                    seen.push(cand);
429	                }
430	            }
431	        }
432	    }
433	    let found = seen.len();
434	    if found == 0 {
435	        sw!(out, "    none — no single glyph repairs this word");
436	    } else {
437	        sw!(out, "  {} distinct word(s) hold, of {} tried", found, tried);
438	    }
439	    out
440	}
441	
442	/// How many distinct one-glyph insertions make `base` hold, without printing.
443	pub fn repair_count(base: &str) -> usize {
444	    let glyphs = ['⊢', '⊙', '∈', '∋', '⊤', '⊥', '≻', '≺', '⋈', '⊞', '⊡', '⊣'];
445	    let chars: Vec<char> = base.chars().collect();
446	    let n = chars.len();
447	    let mut seen: Vec<String> = Vec::new();
448	    for pos in 0..=n {
449	        for g in glyphs.iter() {
450	            let mut cand = String::new();
451	            for (k, c) in chars.iter().enumerate() {
452	                if k == pos { cand.push(*g); }
453	                cand.push(*c);
454	            }
455	            if pos == n { cand.push(*g); }
456	            if seen.iter().any(|w| w == &cand) { continue; }
457	            if let Some(b) = banked_walk(&cand) {
458	                if b.holds() { seen.push(cand); }
459	            }
460	        }
461	    }
462	    seen.len()
463	}
464	
465	
466	/// Count what the union throws away.
467	pub fn weight_report(word: &str) -> String {
468	    let mut out = String::new();
469	    let steps = parse_glyph_word(&normalize(word));
470	    if steps.is_empty() {
471	        sw!(out, "  no IMASM glyphs in that word");
472	        return out;
473	    }
474	    sw!(out, "word   : {}", render(&steps));
475	
476	    // Base values are indexed T, F, t, f throughout.
477	    const NAMES: [&str; 4] = ["T", "F", "t", "f"];
478	    let mut reg = [0u32; 4];
479	    let mut frames: Vec<[u32; 4]> = Vec::new();
480	    let (mut deposits, mut cleared, mut restored, mut seeded, mut inert) =
481	        (0u32, 0u32, 0u32, 0u32, 0u32);
482	    let mut fixed = false;
483	    let mut nonempty = false;
484	
485	    sw!(out, "  movement:");
486	    for (i, t) in steps.iter().enumerate() {
487	        let step = i + 1;
488	        let g = t.glyph();
489	
490	        // The machine returns early once IFIX has fired: everything but IFIX
491	        // and IMSCRIB is inert. Counting a movement without the same guard
492	        // reports clears and fuses that never happened.
493	        if fixed && !matches!(t, Token16_3::Ifix | Token16_3::Imscrib) {
494	            inert += 1;
495	            continue;
496	        }
497	
498	        match t {
499	            Token16_3::Fsplit3 => {
500	                frames.push([0; 4]);
501	                sw!(out, "   {:>3} {}  open frame at depth {}", step, g, frames.len());
502	            }
503	            Token16_3::Ffuse3 => {
504	                if let Some(closed) = frames.pop() {
505	                    let mut got = 0u32;
506	                    for j in 0..4 {
507	                        if closed[j] > reg[j] { got += closed[j] - reg[j]; reg[j] = closed[j]; }
508	                        if let Some(outer) = frames.last_mut() {
509	                            if closed[j] > outer[j] { outer[j] = closed[j]; }
510	                        }
511	                    }
512	                    restored += got;
513	                    nonempty = reg.iter().any(|&w| w > 0);
514	                    sw!(out, "   {:>3} {}  fuse restores {}", step, g, got);
515	                }
516	            }
517	            Token16_3::Arev | Token16_3::Vinit => {
518	                let lost: u32 = reg.iter().sum();
519	                let banked: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
520	                cleared += lost;
521	                reg = [0; 4];
522	                if matches!(t, Token16_3::Vinit) { frames.clear(); }
523	                nonempty = false;
524	                sw!(out, "   {:>3} {}  CLEAR loses {}   ({} banked in frames)",
525	                          step, g, lost, banked);
526	            }
527	            Token16_3::Afwd | Token16_3::Imscrib => {
528	                if !nonempty {
529	                    seeded += 1;
530	                    nonempty = true;
531	                    sw!(out, "   {:>3} {}  SEED T into an empty register, no weight", step, g);
532	                }
533	            }
534	            Token16_3::Ifix => { fixed = true; }
535	            _ => {
536	                // The evaluators are the only depositors: EVALT touches T,
537	                // EVALF touches F, EVALI touches t and f together, which is
538	                // why the constructive pair is never seen split.
539	                let touched: &[usize] = match t {
540	                    Token16_3::Evalt => &[0],
541	                    Token16_3::Evalf => &[1],
542	                    Token16_3::Evali => &[2, 3],
543	                    _ => &[],
544	                };
545	                if !touched.is_empty() {
546	                    let mut names = String::new();
547	                    for &j in touched {
548	                        reg[j] += 1;
549	                        if let Some(f) = frames.last_mut() { f[j] += 1; }
550	                        if !names.is_empty() { names.push('+'); }
551	                        names.push_str(NAMES[j]);
552	                    }
553	                    deposits += 1;
554	                    nonempty = true;
555	                    sw!(out, "   {:>3} {}  deposit {}   into depth {}",
556	                              step, g, names, frames.len());
557	                }
558	            }
559	        }
560	    }
561	
562	    let mut surv = String::new();
563	    for j in 0..4 {
564	        if reg[j] > 0 {
565	            if !surv.is_empty() { surv.push_str(", "); }
566	            surv.push_str(&format!("{}×{}", NAMES[j], reg[j]));
567	        }
568	    }
569	    let stranded: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
570	    sw!(out, "");
571	    sw!(out, "  final    : {}", run_word_register(&steps));
572	    sw!(out, "  surviving: {}", if surv.is_empty() { "none" } else { &surv });
573	    sw!(out, "  deposits {}  cleared {}  restored {}  seeded {}  inert {}",
574	              deposits, cleared, restored, seeded, inert);
575	    if stranded > 0 {
576	        sw!(out, "  stranded in frames never fused: {}", stranded);
577	    }
578	    out
579	}
580

