1	// combo.rs — cycle a word, then run the full instrument suite on every
2	// distinct rotation.
3	//
4	// `cycle` alone answers one question: where does each cut land. It does not
5	// say whether any of those rotations is itself exposed, repairable, or
6	// already holding. This runs weight, banked, insert, and repair on each one,
7	// so the whole orbit gets the same standing audit a single word already gets
8	// from `imasm write`/`imasm derive` -- just walked across every rotation
9	// instead of the one the caller happened to write down.
10	
11	#![allow(dead_code)]
12	extern crate alloc;
13	
14	use crate::sprintln;
15	use alloc::string::String;
16	use alloc::vec::Vec;
17	use imasm_core::lattice_flow::normalize;
18	
19	/// The rotations of a normalized word, as plain strings, one per cut.
20	/// Deduplicated: a word with rotational symmetry (period dividing its
21	/// length) repeats some cuts verbatim, and there is nothing new to learn
22	/// running the same string through the suite twice.
23	fn distinct_rotations(word: &str) -> Vec<(usize, String)> {
24	    let norm = normalize(word);
25	    let chars: Vec<char> = norm.chars().collect();
26	    let n = chars.len();
27	    let mut out: Vec<(usize, String)> = Vec::new();
28	    let mut seen: Vec<String> = Vec::new();
29	    for k in 0..n {
30	        let rot: String = chars[k..].iter().chain(chars[..k].iter()).collect();
31	        if seen.iter().any(|w| w == &rot) { continue; }
32	        seen.push(rot.clone());
33	        out.push((k, rot));
34	    }
35	    out
36	}
37	
