92	        let y = if i < bv.len() { bv[i] - b'0' } else { 0 };
93	        let s = x + y + carry;
94	        out.push(b'0' + s % 10);
95	        carry = s / 10;
96	    }
97	    if carry > 0 { out.push(b'0' + carry); }
98	    let s: String = out.iter().rev().map(|c| *c as char).collect();
99	    trim(&s)
