132	/// a mod d. d is small (<= 1_000_000_000). Returns the small remainder.
133	/// Full-precision schoolbook: never rounds.
134	fn rem_small(a: &str, d: u64) -> u64 {
135	    let mut r: u64 = 0;
136	    for c in a.bytes() {
137	        // r is always < d here, and d <= 1e9, so r*10 + digit < 1e10, fits u64.
138	        // For d up to ~1.84e18 this is exact. We use u128 for the product+carry
139	        // to guarantee no overflow even if d grows to 1e18.
140	        r = (r as u128 * 10 + (c - b'0') as u128 % d as u128) as u64 % d;
141	    }
142	    r
143	}
