145	/// True if d (u64) divides a exactly.
146	fn divisible_by(a: &str, d: u64) -> bool {
147	    if d < 10 {
148	        // Fast path for small divisors
149	        match d {
150	            1 => true,
151	            2 => is_even(a),
152	            3 => rem_small(a, 3) == 0,
153	            4 => {
154	                let r = rem_small(a, 100);
155	                r % 4 == 0
156	            }
157	            5 => last_digit(a) == 0 || last_digit(a) == 5,
158	            6 => is_even(a) && rem_small(a, 3) == 0,
159	            7 => rem_small(a, 7) == 0,
160	            8 => rem_small(a, 1000) % 8 == 0,
161	            9 => rem_small(a, 9) == 0,
162	            _ => false,
163	        }
164	    } else {
165	        rem_small(a, d) == 0
166	    }
167	}
