169	/// a / d for small u64 divisor d, returns string. Exact division.
170	/// Schoolbook: r is bounded by d, so r*10+digit < 10*d <= 1e19, fits in u128.
171	fn div_small(a: &str, d: u64) -> String {
172	    let mut out: Vec<u8> = Vec::new();
173	    let mut r: u128 = 0;
174	    for c in a.bytes() {
175	        r = r * 10 + (c - b'0') as u128;
176	        let q = (r / d as u128) as u8;
177	        if !out.is_empty() || q > 0 {
178	            out.push(b'0' + q);
179	        }
180	        r %= d as u128;
181	    }
182	    if out.is_empty() { String::from("0") } else { String::from_utf8(out).unwrap() }
