226	/// division only up to d=10,000,000 and then silently fall through to
227	/// `true` regardless of whether a factor had actually been ruled out past
228	/// that point -- so any number whose smallest prime factor exceeds 1e7 was
229	/// reported prime unconditionally. That is every real RSA modulus by
230	/// construction (both factors are always far larger than 1e7). Verified
231	/// against the real RSA-100 challenge modulus (a published, historical,
232	/// definitely-composite 100-digit semiprime, confirmed composite via
233	/// sympy.isprime): this function used to return true on it.
234	pub fn is_prime(a: &str) -> bool {
235	    let t = trim(a);
236	    if t == "1" || t == "0" { return false; }
237	    if t == "2" { return true; }
238	    if is_even(&t) { return false; }
239	    // Quick small-prime sieve
240	    if divisible_by(&t, 3) { return t == "3"; }
241	    if divisible_by(&t, 5) { return t == "5"; }
242	    if divisible_by(&t, 7) { return t == "7"; }
243	    if divisible_by(&t, 11) { return t == "11"; }
244	    if divisible_by(&t, 13) { return t == "13"; }
245	
246	    // For numbers that fit in u64, trial division to sqrt is exact and fast.
247	    if t.len() <= 18 {
248	        if let Ok(n) = t.parse::<u64>() {
249	            let mut d: u64 = 17;
250	            while d * d <= n {
251	                if n % d == 0 { return false; }
252	                d += 2;
253	            }
254	            return true;
255	        }
256	    }
