281	/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
282	pub fn find(n: &str) -> String {
283	    if lt(n, "2") {
284	        return format!("prime_winding find {}: no primes ≤ {}", n, n);
285	    }
286	    if is_prime(n) {
