310	/// Factor n (decimal string, arbitrary precision) into primes with multiplicity.
311	///
312	/// FIXED 2026-08-31: the same false-positive class as `is_prime`. Trial
313	/// division ran to a fixed cap (d > 1,000,000) and, on hitting it, pushed
314	/// whatever remained as though it were a single prime factor -- so a large
315	/// semiprime with no factor below the cap (an RSA modulus, by construction)
316	/// was reported as prime with no factors at all. Now checks the leftover
317	/// cofactor with `is_prime` (real Miller-Rabin) before ever calling it
318	/// prime, and says plainly when trial division could not finish the split.
319	pub fn factor(n: &str) -> String {
320	    if lt(n, "2") {
321	        return format!("prime_winding factor {}: n < 2, no prime factors", n);
322	    }
323	    let mut m = trim(n);
324	    let mut factors: Vec<String> = Vec::new();
325	
326	    while is_even(&m) {
327	        factors.push(String::from("2"));
328	        m = div_small(&m, 2);
329	    }
330	    let mut d: u64 = 3;
331	    loop {
332	        let d2 = (d as u128 * d as u128).to_string();
333	        // Break only once d^2 exceeds m -- d^2 == m (m a perfect square of
334	        // the next divisor, e.g. m=25 at d=5) must still be tested, or that
335	        // divisor is silently skipped. Was `!lt(&d2, &m)`, which broke one
336	        // step early on exactly that boundary; caught live testing 100.
337	        if lt(&m, &d2) { break; }
338	        while rem_small(&m, d) == 0 {
339	            factors.push(d.to_string());
340	            m = div_small(&m, d);
341	        }
342	        d += 2;
343	        if d > 1_000_000 { break; }
344	    }
345	
346	    if !is_zero(&m) && m != "1" {
347	        if is_prime(&m) {
348	            factors.push(m.clone());
349	        } else if factors.is_empty() {
350	            return format!(
351	                "prime_winding factor {}: {} is composite (Miller-Rabin) but has no factor below 1,000,000 — trial division cannot split it further",
352	                n, n
353	            );
354	        } else {
355	            let rep = factors.join(" × ");
356	            return format!(
357	                "prime_winding factor {}: {} = {} × <composite cofactor {}> — trial division found no further factor below 1,000,000, and Miller-Rabin confirms the cofactor is not prime",
358	                n, n, rep, m
359	            );
360	        }
361	    }
362	
363	    if factors.is_empty() {
364	        return format!("prime_winding factor {}: {} IS PRIME", n, n);
365	    }
366	    let distinct: bool = factors.len() == 1 && factors[0] == n;
367	    if distinct {
368	        format!("prime_winding factor {}: {} IS PRIME", n, n)
369	    } else {
370	        let rep = factors.join(" × ");
371	        format!("prime_winding factor {}: {} = {}", n, n, rep)
372	    }
373	}
