191	/// Returns (confirmed prime factors, unfactored composite cofactors).
192	///
193	/// FIXED 2026-08-31: on a Brent failure this used to push the cofactor `m`
194	/// straight into the factor list with a "conservative: treat as prime"
195	/// comment -- but `m` had already failed `is_prime_big` (real Miller-Rabin)
196	/// one line above, so this was never conservative, it was wrong: a known
197	/// composite got reported as though it were a prime factor. Brent's rho has
198	/// no guaranteed success bound, and an RSA-scale semiprime (each factor far
199	/// past what ~4e6 Brent steps can reach) reliably triggers it -- verified
200	/// live: `nested_oneshot factor` on the real RSA-100-scale modulus this
201	/// session's other tests used printed "N = N", claiming the whole composite
202	/// modulus as its own sole factor. Now the two cases are kept apart.
203	fn factor_recursive_big(mut n: BigUint) -> (Vec<BigUint>, Vec<BigUint>) {
204	    let mut factors: Vec<BigUint> = Vec::new();
205	    let mut unfactored: Vec<BigUint> = Vec::new();
206	    let two = BigUint::from(2u32);
207	    while &n % &two == BigUint::zero() {
208	        factors.push(two.clone());
209	        n /= 2u32;
210	    }
211	    let mut stack: Vec<BigUint> = Vec::new();
212	    if !n.is_one() { stack.push(n); }
213	    while let Some(m) = stack.pop() {
214	        if m.is_one() { continue; }
215	        if is_prime_big(&m) { factors.push(m); continue; }
216	        if let Some(f) = brent_factor_big(&m) {
217	            let g = &m / &f;
218	            if f >= g {
219	                stack.push(f);
220	                stack.push(g);
221	            } else {
222	                stack.push(g);
223	                stack.push(f);
224	            }
225	        } else {
226	            unfactored.push(m); // confirmed composite, Brent could not split it
227	        }
228	    }
229	    factors.sort_unstable();
230	    unfactored.sort_unstable();
231	    (factors, unfactored)
232	}
