        let rep: Vec<String> = undetermined.iter().map(|p| p.to_str_radix(10)).collect();
        out.push_str(&format!(
            "\n  └─ cofactor(s) whose primality itself did not close within the step budget: {}",
            rep.join(" × ")
        ));
    }
    out
}

