                        sprintln!("  Witness: c={} (depth-d closure seed).", c);
                        sprintln!("  Result: μ∘δ = id at depth {} with non-trivial fold.", d);
                        return;
                    }
                    None => {
                        sprintln!("    no closure at d={} (cycle did not yield a factor)", d);
                    }
                }
            }
