126	    // write n-1 = d * 2^s with d odd
127	    let n_minus_1 = n - 1u32;
128	    let mut s: u32 = 0;
129	    let mut d = n_minus_1.clone();
130	    let two_b = BigUint::from(2u32);
131	    while &d % &two_b == BigUint::zero() {
132	        d /= 2u32;
133	        s += 1;
