159	// Brent's cycle detection (fold/kiss topology) — arbitrary length
160	fn brent_factor_big(n: &BigUint) -> Option<BigUint> {
161	    let two = BigUint::from(2u32);
162	    if n % 2u32 == BigUint::zero() { return Some(two.clone()); }
163	    if n.is_one() { return None; }
164	
165	    let c_candidates: [u64; 4] = [3, 7, 11, 17];
166	    let n_mod_97 = (n % BigUint::from(97u32)).to_u64().unwrap_or(0);
167	
168	    for (i, &base_c) in c_candidates.iter().enumerate() {
169	        let c_raw = base_c.wrapping_add((n_mod_97 as u64).wrapping_mul(i as u64 + 1)) % 1_000_000;
170	        let c = BigUint::from(if c_raw == 0 { 1u64 } else { c_raw });
171	
172	        let x_init = BigUint::from(2u64 + (n_mod_97 % 95));
173	        let mut x: BigUint = x_init.clone();
174	        let m: u64 = 128;
175	        let mut power: u64 = 1;
176	        #[allow(unused_assignments)]
177	        let mut y: BigUint = x.clone();
178	
179	        while power < 1_000_000 {
180	            let mut step: u64 = 0;
181	            while step < power {
182	                x = brent_f(&x, &c, n);
183	                step += 1;
184	            }
185	            y = x.clone();
186	            let upper = power.min(m);
187	            let mut j: u64 = 0;
188	            while j < upper {
189	                x = brent_f(&x, &c, n);
190	                let d = if x > y { &x - &y } else { &y - &x };
191	                let g = big_gcd(d, n.clone());
192	                if !g.is_one() && g != *n { return Some(g); }
193	                j += 1;
194	            }
195	            power = match power.checked_mul(2) {
196	                Some(p) => p,
197	                None => break,
198	            };
199	        }
200	    }
201	    None
202	}
