204	/// Returns (confirmed prime factors, unfactored composite cofactors).
205	///
206	/// FIXED 2026-08-31: same bug as nested_oneshot.rs's copy of this function --
207	/// on a Brent failure it pushed the cofactor `m` straight into the factor
208	/// list, even though `m` had already failed `is_prime_big` (real
209	/// Miller-Rabin) one line above. A confirmed composite got reported as a
210	/// prime factor whenever Brent's rho (no guaranteed success bound) failed
211	/// to split it, which any RSA-scale semiprime reliably triggers.
212	fn factor_recursive_big(mut n: BigUint) -> (Vec<BigUint>, Vec<BigUint>) {
213	    let mut factors: Vec<BigUint> = Vec::new();
214	    let mut unfactored: Vec<BigUint> = Vec::new();
215	    let two = BigUint::from(2u32);
216	    while &n % &two == BigUint::zero() {
217	        factors.push(two.clone());
218	        n /= 2u32;
219	    }
220	    let mut stack: Vec<BigUint> = Vec::new();
221	    if !n.is_one() { stack.push(n); }
222	    while let Some(m) = stack.pop() {
223	        if m.is_one() { continue; }
224	        if is_prime_big(&m) { factors.push(m); continue; }
225	        if let Some(f) = brent_factor_big(&m) {
226	            let g = &m / &f;
227	            if f >= g {
228	                stack.push(f);
229	                stack.push(g);
230	            } else {
231	                stack.push(g);
232	                stack.push(f);
233	            }
234	        } else {
235	            unfactored.push(m); // confirmed composite, Brent could not split it
236	        }
237	    }
238	    factors.sort_unstable();
239	    unfactored.sort_unstable();
240	    (factors, unfactored)
241	}
