243	fn collect_factors_big(n_str: &str) -> (Vec<BigUint>, Vec<BigUint>) {
244	    let t = trim(n_str);
245	    if t.is_empty() || t == "0" { return (Vec::new(), Vec::new()); }
246	    match parse_big(&t) {
247	        Some(ref n) if n > &BigUint::one() => factor_recursive_big(n.clone()),
248	        _ => (Vec::new(), Vec::new()),
249	    }
250	}
