269	        sprintln!("  N has ARBITRARY LENGTH (BigUint, no fixed digit limit).");
270	        sprintln!("  Returns B4 verdict: T (prime), F (composite), B (paradice).");
271	        sprintln!("  Subcommands:");
272	        sprintln!("    dnos word        — canonical glyph word");
273	        sprintln!("    dnos cycle       — ROTAT orbit with landing register");
274	        sprintln!("    dnos verdict N   — B4 verdict for N");
275	        sprintln!("    dnos winding    — winding number");
276	        sprintln!("    dnos landings    — landing register states by k");
277	        sprintln!("    dnos factor N   — oneshot factor via Brent fold/kiss (arbitrary length)");
278	        sprintln!("  Examples:");
279	        sprintln!("    dnos 17");
280	        sprintln!("    dnos factor 1234567");
281	        sprintln!("    dnos factor 99999999999999999999999999999999999999999");
282	        return;
283	    }
284	
285	    let sub = args[0];
286	    match sub {
287	        "word" => {
288	            sprintln!("word            : {}", WORD);
289	            sprintln!("period          : {}", PERIOD);
290	            sprintln!("phase-bearing   : {}", PHASE_BEARING);
291	            sprintln!("nesting depth   : 2 (outer frame wraps inner)");
292	        }
293	        "cycle" => {
294	            sprintln!("word: {}   period {}", WORD, PERIOD);
295	            sprintln!("  k  landing");
296	            sprintln!("  ─── ───────");
297	            for k in 0..PERIOD { sprintln!("  {:3}  {}", k, landing_at(k)); }
298	            sprintln!("5 distinct landings: A, Ftf, Ttf, tf, T");
299	        }
300	        "verdict" => {
301	            if args.len() < 2 { sprintln!("Usage: dnos verdict <N>"); return; }
302	            let n = args[1];
303	            let v = verdict_for(n);
304	            let desc = match &v {
305	                B4Verdict::T => "one-shot closure (prime)",
306	                B4Verdict::F => "no closure (composite)",
307	                B4Verdict::B => "paradice (neither prime nor composite)",
308	            };
309	            sprintln!("doubly_nested_oneshot verdict {}: {}", n, v);
310	            sprintln!("  └─ {}", desc);
311	        }
312	        "winding" => { sprintln!("winding: {}", winding_number()); }
313	        "landings" => {
314	            sprintln!("landing register by ROTAT cut (k=0..15):");
315	            for k in 0..PERIOD { sprintln!("  k={:2}: {}", k, landing_at(k)); }
316	        }
317	        "factor" => {
318	            if args.len() < 2 { sprintln!("Usage: dnos factor <N>"); return; }
319	            let n = args[1];
320	            let v = verdict_for(n);
321	            match v {
322	                B4Verdict::B => {
323	                    sprintln!("doubly_nested_oneshot factor {}: B — paradice (1 is the unit)", n);
324	                }
