328	                        sprintln!("doubly_nested_oneshot factor {}: F — could not factor (non-numeric input?)", n);
329	                    } else {
330	                        let group = |xs: &[BigUint]| -> Vec<String> {
331	                            let mut reps: Vec<String> = Vec::new();
332	                            let mut i = 0usize;
333	                            while i < xs.len() {
334	                                let p = &xs[i];
335	                                let mut cnt = 1usize;
336	                                while (i + cnt) < xs.len() && &xs[i + cnt] == p {
337	                                    cnt += 1;
338	                                }
339	                                if cnt == 1 { reps.push(big_to_string(p)); }
340	                                else { reps.push(alloc::format!("{}^{}", big_to_string(p), cnt)); }
341	                                i += cnt;
342	                            }
343	                            reps
344	                        };
345	                        sprintln!("doubly_nested_oneshot factor {}: F — composite (doubly-nested fold)", n);
346	                        if !factors.is_empty() {
347	                            sprintln!("  └─ confirmed prime factors: {}", group(&factors).join(" × "));
348	                        }
349	                        if !unfactored.is_empty() {
350	                            sprintln!("  └─ unfactored composite cofactor(s), Brent could not split (confirmed NOT prime by Miller-Rabin): {}", group(&unfactored).join(" × "));
351	                        }
352	                    }
353	                }
354	                B4Verdict::T => {
355	                    sprintln!("doubly_nested_oneshot factor {}: T — prime (no non-trivial factors)", n);
356	                }
357	            }
358	        }
359	        _ => {
360	            let n = sub;
361	            let v = verdict_for(n);
362	            let desc = match &v {
363	                B4Verdict::T => "prime",
364	                B4Verdict::F => "composite",
365	                B4Verdict::B => "paradice",
366	            };
367	            sprintln!("{}", v);
368	            sprintln!("  └─ {}: {} (doubly-nested)", desc, n);
369	        }
370	    }
371	}
