cd ~/imsgct
python3 << 'EOF'
import sympy

GLYPHS = "⊢⊣≻≺⋈⊤∈∋⊙⊥⊞⊡"  # index matches: 0 VINIT,1 TANCH,2 AFWD,3 AREV,4 CLINK,5 EVALT,6 FSPLIT,7 FFUSE,8 IMSCRIB,9 EVALF,10 ENGAGR,11 IFIX
VINIT,TANCH,AFWD,AREV,CLINK,EVALT,FSPLIT,FFUSE,IMSCRIB,EVALF,ENGAGR,IFIX = GLYPHS
WORK = set([AFWD,AREV,CLINK,EVALT,EVALF,ENGAGR,IFIX])

def bytes_to_word(n: int) -> str:
    if n == 0:
        b = b'\x00'
    else:
        b = n.to_bytes((n.bit_length()+7)//8, 'big')
    return ''.join(GLYPHS[byte % 12] for byte in b)

def cyclic_pairs(word):
    n = len(word)
    balance = 0
    least = 0
    start = 0
    for i in range(n):
        if word[i] == FSPLIT: balance += 1
        elif word[i] == FFUSE: balance -= 1
        if balance < least:
            least = balance
            start = (i+1) % n
    stack = []
    pairs = []
    un_fuse = []
    for off in range(n):
        i = (start+off) % n
        if word[i] == FSPLIT:
            stack.append(i)
        elif word[i] == FFUSE:
            if stack:
                si = stack.pop()
                pairs.append((si, i))
            else:
                un_fuse.append(i)
    un_split = sorted(stack)
    un_fuse.sort()
    return pairs, un_split, un_fuse

def cyclic_interior(word, si, fj):
    n = len(word)
    length = (fj + n - si - 1) % n
    return [word[(si+1+j) % n] for j in range(length)]

def verdict(word):
    pairs, un_split, un_fuse = cyclic_pairs(word)
    if not pairs and not un_split and not un_fuse:
        return 'N'
    if len(un_fuse) > len(un_split):
        return 'F'
    if un_split:
        return 'B'
    for si, fj in pairs:
        if any(c in WORK for c in cyclic_interior(word, si, fj)):
            return 'T'
    return 'N'

# Test on a range of numbers
primes_test = list(sympy.primerange(2, 200))
composites_test = [n for n in range(4, 200) if not sympy.isprime(n)]

def closed(v): return v in ('T','N')

correct = 0
total = 0
mismatches = []
for n in primes_test + composites_test:
    w = bytes_to_word(n)
    v = verdict(w)
    is_prime_actual = sympy.isprime(n)
    predicted_prime = closed(v)
    total += 1
    if predicted_prime == is_prime_actual:
        correct += 1
    else:
        mismatches.append((n, w, v, is_prime_actual))

print(f"correct: {correct}/{total}")
print("first 20 mismatches:", mismatches[:20])
EOF

