111	/// The three outcomes an order-based primality search can reach. Never
112	/// collapsed to a bool: Undetermined is a real, distinct answer, not a
113	/// stand-in for either Prime or Composite.
114	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
115	pub enum PrimeVerdict { Prime, Composite, Undetermined }
116	
117	/// Order r of a mod N divides N-1 iff a^(N-1) == 1 mod N (Fermat), so a
118	/// base whose order does NOT divide N-1 proves N composite outright. A
119	/// base whose order lies OutOfReach makes the verdict Undetermined for
120	/// that base — Composite the moment any one base proves it, Undetermined
121	/// the moment any one base's order sits outside the search's reach, and
122	/// Prime only once every tested base has passed clean.
123	pub fn is_prime(a: &str) -> PrimeVerdict {
124	    let t = trim(a);
125	    let n: BigUint = match t.parse() {
126	        Ok(v) => v,
127	        Err(_) => return PrimeVerdict::Composite,
128	    };
129	    let two = BigUint::from(2u32);
130	    if n < two { return PrimeVerdict::Composite; }
131	    if n == two { return PrimeVerdict::Prime; }
132	    if &n % &two == BigUint::zero() { return PrimeVerdict::Composite; }
133	
134	    let n_minus_1 = &n - BigUint::one();
135	    let bases: [u32; 6] = [2, 3, 5, 7, 11, 13];
136	    for &b in &bases {
137	        let a_b = BigUint::from(b);
138	        if a_b >= n { continue; }
139	        match winding_order_big(&a_b, &n, STEP_CAP) {
140	            WindingBig::Order(r) => {
141	                if r == 0 || &n_minus_1 % BigUint::from(r) != BigUint::zero() {
142	                    return PrimeVerdict::Composite;
143	                }
144	            }
145	            // gcd(a, N) != 1 for a < N means a shares a factor with N.
146	            WindingBig::NotInGroup => return PrimeVerdict::Composite,
147	            WindingBig::OutOfReach => return PrimeVerdict::Undetermined,
148	        }
149	    }
150	    PrimeVerdict::Prime
151	}
