154	    match v {
155	        PrimeVerdict::Prime => "PRIME",
156	        PrimeVerdict::Composite => "COMPOSITE",
157	        PrimeVerdict::Undetermined => "UNDETERMINED (the order lies outside this search's reach)",
158	    }
159	}
