170	/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
171	/// Stops the moment the search meets an Undetermined verdict — it does
172	/// not step past a number outside its reach.
173	pub fn find(n: &str) -> String {
174	    if lt(n, "2") {
175	        return format!("prime_winding find {}: no primes ≤ {}", n, n);
176	    }
177	    let mut m = trim(n);
178	    let mut steps: u64 = 0;
179	    loop {
180	        match is_prime(&m) {
181	            PrimeVerdict::Prime => {
182	                return if steps == 0 {
183	                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, WORD)
184	                } else {
185	                    format!(
186	                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
187	                        n, n, n, m, WORD
188	                    )
189	                };
190	            }
191	            PrimeVerdict::Undetermined => {
192	                return format!(
193	                    "prime_winding find {}: order search on {} did not close within the step budget — cannot certify further",
194	                    n, m
195	                );
196	            }
197	            PrimeVerdict::Composite => {}
198	        }
199	        if lt(&m, "2") {
200	            return format!("prime_winding find {}: no prime found below", n);
201	        }
202	        m = sub(&m, "1");
203	        steps += 1;
204	        if steps > 1_000_000_000 {
205	            return format!("prime_winding find {}: scan limit reached (1B steps)", n);
206	        }
207	    }
208	}
