210	/// Factor n (decimal string, arbitrary precision) via the winding-order
211	/// engine only. Three outcomes per component, none collapsed into the
212	/// others: confirmed prime factors, composite cofactors the Shor step
213	/// could not split within its retries, and cofactors whose own
214	/// primality search never closed at all.
215	pub fn factor(n: &str) -> String {
216	    let t = trim(n);
217	    let n_big: BigUint = match t.parse() {
218	        Ok(v) => v,
219	        Err(_) => return format!("prime_winding factor {}: not a valid non-negative integer", n),
220	    };
221	    if n_big < BigUint::from(2u32) {
222	        return format!("prime_winding factor {}: n < 2, no prime factors", n);
223	    }
224	
225	    let mut m = n_big;
226	    let mut primes: Vec<BigUint> = Vec::new();
227	    let two = BigUint::from(2u32);
228	    while &m % &two == BigUint::zero() {
229	        primes.push(two.clone());
230	        m /= &two;
231	    }
232	
233	    let mut composite_unsplit: Vec<BigUint> = Vec::new();
234	    let mut undetermined: Vec<BigUint> = Vec::new();
235	    let mut stack: Vec<BigUint> = Vec::new();
236	    if m > BigUint::one() { stack.push(m); }
237	    let mut seed: u64 = 0xC0FFEE_1234_5678;
238	
239	    while let Some(cand) = stack.pop() {
240	        if cand == BigUint::one() { continue; }
241	        match is_prime(&cand.to_str_radix(10)) {
242	            PrimeVerdict::Prime => primes.push(cand),
243	            PrimeVerdict::Undetermined => undetermined.push(cand),
244	            PrimeVerdict::Composite => {
245	                seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
246	                match factor_big(&cand, FACTOR_TRIES, STEP_CAP, seed) {
247	                    FactorBig::Found { p, q, .. } => {
248	                        stack.push(p);
249	                        stack.push(q);
250	                    }
251	                    FactorBig::NoFactorInTries | FactorBig::BudgetExceeded => {
252	                        composite_unsplit.push(cand);
253	                    }
254	                }
255	            }
256	        }
257	    }
258	    primes.sort_unstable();
259	    composite_unsplit.sort_unstable();
260	    undetermined.sort_unstable();
261	
262	    if primes.is_empty() && composite_unsplit.is_empty() && undetermined.is_empty() {
263	        return format!("prime_winding factor {}: {} IS PRIME", n, n);
264	    }
265	    if composite_unsplit.is_empty() && undetermined.is_empty() && primes.len() == 1
266	        && primes[0].to_str_radix(10) == trim(n)
267	    {
268	        return format!("prime_winding factor {}: {} IS PRIME", n, n);
269	    }
270	
271	    let mut out = format!("prime_winding factor {}: ", n);
272	    if !primes.is_empty() {
273	        let rep: Vec<String> = primes.iter().map(|p| p.to_str_radix(10)).collect();
274	        out.push_str(&format!("{} = {}", n, rep.join(" × ")));
275	    } else {
276	        out.push_str(&format!("{} — no confirmed prime factors", n));
277	    }
278	    if !composite_unsplit.is_empty() {
279	        let rep: Vec<String> = composite_unsplit.iter().map(|p| p.to_str_radix(10)).collect();
280	        out.push_str(&format!(
281	            "\n  └─ composite cofactor(s), order search could not split within {} tries: {}",
282	            FACTOR_TRIES, rep.join(" × ")
283	        ));
284	    }
285	    if !undetermined.is_empty() {
286	        let rep: Vec<String> = undetermined.iter().map(|p| p.to_str_radix(10)).collect();
287	        out.push_str(&format!(
288	            "\n  └─ cofactor(s) whose primality itself did not close within the step budget: {}",
289	            rep.join(" × ")
290	        ));
291	    }
292	    out
293	}
