    let mut undetermined: Vec<BigUint> = Vec::new();
    let mut stack: Vec<BigUint> = Vec::new();
    if m > BigUint::one() { stack.push(m); }
    let mut seed: u64 = 0xC0FFEE_1234_5678;

    while let Some(cand) = stack.pop() {
