/// which is why the host `ask` binary could not use them. They build a String
/// now and the kernel prints it; `sw!` is the one-line shim that made the move
/// mechanical rather than a rewrite.
macro_rules! sw {
    ($o:expr) => {{ $o.push('\n'); }};
    ($o:expr, $($t:tt)*) => {{
        use core::fmt::Write as _;
        let _ = write!($o, $($t)*);
        $o.push('\n');
    }};
}

