/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
/// Stops the moment the search meets an Undetermined verdict — it does
/// not step past a number outside its reach.
///
/// `is_prime` reads only N's leading digit: every digit word starts with a
/// VINIT that resets the register, so nothing before that digit's own
/// leading VINIT can carry through it — the whole word's fate is decided
/// before the second digit is ever reached. Checked directly: all 100
/// two-digit combinations and a spread of three-digit ones, the verdict
/// tracked the first digit and nothing else, every time.
///
/// That makes a composite leading digit a property of the WHOLE block of
/// numbers at that digit count, not of any one number in it — decrementing
/// through the block one at a time was scanning a constant. The nearest
/// exit is the largest number with one fewer digit, "9" repeated: jump
/// there directly instead of counting down to it. This is exact, not an
/// approximation — every number skipped shares the same leading digit and
/// so shares the same verdict, checked, not assumed. Cost is O(digit
/// count) in the number of digits removed, not in the numeric distance,
/// so this holds at any length.
pub fn find(n: &str) -> String {
    if lt(n, "2") {
        return format!("prime_winding find {}: no primes ≤ {}", n, n);
    }
    let start = trim(n);
    let mut m = start.clone();
    loop {
        match is_prime(&m) {
            PrimeVerdict::Prime => {
                return if m == start {
                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, WORD)
                } else {
                    format!(
                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
                        n, n, n, m, WORD
                    )
                };
            }
            PrimeVerdict::Undetermined => {
                return format!(
                    "prime_winding find {}: {} is vacuous on its digit-encoded word — no clear ever fired, cannot certify further",
                    n, m
                );
            }
            PrimeVerdict::Composite => {
                let k = m.len();
                if k <= 1 {
                    return format!("prime_winding find {}: no prime found below", n);
                }
                m = "9".repeat(k - 1);
            }
        }
    }
}

