130	/// N is prime iff the banking on its digit-encoded word already holds —
131	/// closed is prime, open (an exposed clear with nothing banked behind
132	/// it) is composite. Linear in digit count; no step budget, because
133	/// there is no search here to run out of budget.
134	pub fn is_prime(a: &str) -> PrimeVerdict {
135	    let t = trim(a);
136	    let n: BigUint = match t.parse() {
137	        Ok(v) => v,
138	        Err(_) => return PrimeVerdict::Composite,
139	    };
140	    if n < BigUint::from(2u32) { return PrimeVerdict::Composite; }
