170	/// not step past a number outside its reach.
171	///
172	/// `is_prime` reads only N's leading digit: every digit word starts with a
173	/// VINIT that resets the register, so nothing before that digit's own
174	/// leading VINIT can carry through it — the whole word's fate is decided
175	/// before the second digit is ever reached. Checked directly: all 100
176	/// two-digit combinations and a spread of three-digit ones, the verdict
177	/// tracked the first digit and nothing else, every time.
178	///
179	/// That makes a composite leading digit a property of the WHOLE block of
180	/// numbers at that digit count, not of any one number in it — decrementing
181	/// through the block one at a time was scanning a constant. The nearest
182	/// exit is the largest number with one fewer digit, "9" repeated: jump
183	/// there directly instead of counting down to it. This is exact, not an
184	/// approximation — every number skipped shares the same leading digit and
185	/// so shares the same verdict, checked, not assumed. Cost is O(digit
186	/// count) in the number of digits removed, not in the numeric distance,
187	/// so this holds at any length.
188	pub fn find(n: &str) -> String {
189	    if lt(n, "2") {
190	        return format!("prime_winding find {}: no primes ≤ {}", n, n);
191	    }
192	    let start = trim(n);
193	    let mut m = start.clone();
194	    loop {
195	        match is_prime(&m) {
196	            PrimeVerdict::Prime => {
197	                return if m == start {
198	                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, WORD)
199	                } else {
200	                    format!(
201	                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
202	                        n, n, n, m, WORD
203	                    )
204	                };
205	            }
206	            PrimeVerdict::Undetermined => {
207	                return format!(
208	                    "prime_winding find {}: {} is vacuous on its digit-encoded word — no clear ever fired, cannot certify further",
209	                    n, m
210	                );
