/// N is prime iff the register A (all four of T, F, t, f touched) appears
/// anywhere in the landing spectrum of its hex-encoded word's full ROTAT
/// orbit; Undetermined iff the landing is invariant under ROTAT (the same
/// register at every cut — nothing in the word ever responds to where it's
/// read from); Composite otherwise (phase-bearing, but A never reached).
///
/// This replaced a single-cut banking check (`banked_walk` at k=0 alone)
/// after that check was proven, against all 100 two-digit and a spread of
/// three-digit combinations, to read only the leading digit -- every digit
/// after the first was provably inert, because each digit's word opens on
/// its own VINIT and nothing survives that reset except one boundary fact
/// about the digit before it. The full orbit does not have that blind
/// spot: checked the same way, concatenating any two of the sixteen hex
/// words and walking every rotation shows the trailing nibble's own
/// deposits in the landing spectrum even when the leading nibble alone
/// would have made banked_walk read the same thing regardless. Row-constant
/// became false under this rule where it was true under the old one.
pub fn is_prime(a: &str) -> PrimeVerdict {
    let t = trim(a);
    let n: BigUint = match t.parse() {
        Ok(v) => v,
        Err(_) => return PrimeVerdict::Composite,
    };
    if n < BigUint::from(2u32) { return PrimeVerdict::Composite; }

    let word = digit_encode(&t);
