/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
/// Stops the moment the search meets an Undetermined verdict — it does
/// not step past a number outside its reach.
///
/// The old version of this search jumped straight past a whole block of
/// numbers on the strength of a fact that no longer holds: `is_prime` used
/// to read only the leading digit, so an entire digit-count's worth of
/// numbers shared one verdict and could be skipped at once. Now that the
/// verdict comes from the full ROTAT orbit and genuinely depends on every
/// digit, that shortcut is gone, and there is no known way to jump to the
/// answer — decrementing one at a time is the search, not a stand-in for
/// a faster one. `SCAN_CAP` bounds it at a step count measured to stay
/// interactive; past that it reports OutOfReach honestly rather than
/// pretending completeness or hanging silently.
pub fn find(n: &str) -> String {
    if lt(n, "2") {
        return format!("prime_winding find {}: no primes ≤ {}", n, n);
    }
    let start = trim(n);
    let mut m = start.clone();
    let mut steps: u64 = 0;
    loop {
        match is_prime(&m) {
            PrimeVerdict::Prime => {
                return if m == start {
                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, WORD)
                } else {
                    format!(
                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
                        n, n, n, m, WORD
                    )
                };
            }
            PrimeVerdict::Undetermined => {
                return format!(
                    "prime_winding find {}: {} is vacuous on its digit-encoded word — no clear ever fired, cannot certify further",
                    n, m
                );
            }
            PrimeVerdict::Composite => {}
        }
        if lt(&m, "2") {
            return format!("prime_winding find {}: no prime found below", n);
        }
        m = sub(&m, "1");
        steps += 1;
        if steps > SCAN_CAP {
            return format!(
                "prime_winding find {}: OutOfReach — {} step(s) scanned below {} with no closing or vacuous word, scan halted at {}",
                n, steps, n, m
            );
        }
    }
}

