input.new_string:
/// N is prime iff the Grammar's own tri-ancestral verdict on its hex-encoded
/// word is T — every FSPLIT3 pairs with a FFUSE3 around the word read AS A
/// LOOP, and real work ran inside at least one paired region: a closed,
/// non-trivial transformation. N (paired but no work ran anywhere — void)
/// is Undetermined. B (a fork left open) and F (a fuse with nothing to
/// pair with) both fail to close, so both read Composite.
///
/// This is not a rule built on top of the register content — it is the
/// Grammar's own existing verdict function
/// (`imasm_core::imasm16_3::tri_ancestral_verdict`, exposed here as
/// `tri_ancestral_word_verdict`), already used everywhere an ob3ect reports
/// its own tri-ancestral verdict. Two earlier attempts built a rule on top
/// of the register content instead of asking what the Grammar already
/// computes: a single-cut banking check (`banked_walk` at k=0 alone) was
/// proven to read only the leading digit and nothing after it; a
/// register-A-anywhere check on the full orbit fixed that but turned out
/// to be satisfied by nearly any sufficiently long word, discriminating
/// almost nothing. This reads the word's own verdict instead of inventing
/// one, and that verdict is inherently a whole-loop fact: pairing is
/// cyclic, so it is not one cut among many, it does not need the orbit
/// walked at all.
pub fn is_prime(a: &str) -> PrimeVerdict {
    let t = trim(a);
    let n: BigUint = match t.parse() {
        Ok(v) => v,
        Err(_) => return PrimeVerdict::Composite,
    };
    if n < BigUint::from(2u32) { return PrimeVerdict::Composite; }

    let word = digit_encode(&t);
    match tri_ancestral_word_verdict(&word) {
        Some('T') => PrimeVerdict::Prime,
        Some('N') => PrimeVerdict::Undetermined,
        Some('B') | Some('F') => PrimeVerdict::Composite,
        Some(_) | None => PrimeVerdict::Undetermined,
    }
}

